/**
 * Audit Trail API Service
 *
 * Provides access to audit trail/access logs data.
 * Now uses real API calls to the backend endpoint.
 */

import AbstractApiService from 'src/services/abstractApiService';
import { api } from 'src/pages/APIs';

export interface AuditTrailParams {
  start_time?: string; // ISO 8601
  end_time?: string; // ISO 8601
  hours?: number; // Alternative to start_time/end_time - hours to look back
  resource_types?: string; // Comma-separated
  action_types?: string; // Comma-separated
  search?: string;
  limit?: number;
  offset?: number;
  page?: number;
  page_size?: number;
}

export interface PaginationInfo {
  current_page: number;
  page_size: number;
  offset: number;
  next_offset: number | null;
  has_next_page: boolean;
}

export interface AuditTrailResponse {
  success: boolean;
  data: {
    logs: AuditLogEntry[];
    total_count: number;
    query_info: {
      start_time: string;
      end_time: string;
      filters_applied: string[];
    };
    pagination?: PaginationInfo;
  };
}

export interface AuditLogEntry {
  id: string;
  timestamp: string;
  user_name: string;
  user_email: string;
  action: string;
  resource_type: string;
  resource_name: string;
  resource_id: string;
  activity: string;
  changes: AuditLogChange[];
  success: boolean;
  ip_address: string;
  metadata: {
    table_schema: string;
    table_name: string;
    record_version: number;
  };
  record?: Record<string, any>;
  old_record?: Record<string, any>;
}

export interface AuditLogChange {
  field: string;
  old_value: any;
  new_value: any;
  display_name?: string;
  change_type?: 'creation' | 'modification' | 'deletion';
}

export interface AuditMetricsParams {
  hours?: number;
  action_types?: string; // Comma-separated
  resource_type?: string;
  search?: string;
  start_time?: string; // ISO 8601
  end_time?: string; // ISO 8601
}

export interface AuditMetricsResponse {
  success: boolean;
  data: {
    total_actions: number;
    by_action_type: {
      CREATE: number;
      UPDATE: number;
      DELETE: number;
      VIEW: number;
      EXPORT: number;
    };
    by_resource_type: Record<string, number>;
    time_range: {
      start: string;
      end: string;
      period: string;
    };
  };
}

export default class AuditTrailApiService extends AbstractApiService {
  // Real API calls only - mock data functionality removed

  public constructor() {
    super({});
  }

  /**
   * Get audit trail logs with filtering
   *
   * @param params - Query parameters for filtering
   * @returns Promise with audit trail response
   */
  public async getAuditLogs(
    params: AuditTrailParams = {},
  ): Promise<AuditTrailResponse> {
    // Real API call to backend audit logs endpoint
    const queryParams = new URLSearchParams();
    if (params.start_time) queryParams.append('start_time', params.start_time);
    if (params.end_time) queryParams.append('end_time', params.end_time);
    if (params.hours) queryParams.append('hours', params.hours.toString());
    if (params.resource_types)
      queryParams.append('resource_types', params.resource_types);
    if (params.action_types)
      queryParams.append('action_types', params.action_types);
    if (params.search) queryParams.append('search', params.search);
    if (params.limit) queryParams.append('limit', params.limit.toString());
    if (params.offset !== undefined)
      queryParams.append('offset', params.offset.toString());
    if (params.page) queryParams.append('page', params.page.toString());
    if (params.page_size)
      queryParams.append('page_size', params.page_size.toString());

    return this.getWithoutOrgId(api.audit_logs + '?' + queryParams.toString());
  }

  /**
   * Get detailed changes for a specific audit log entry
   *
   * @param logId - UUID of the audit log entry
   * @returns Promise with detailed change information
   */
  public async getAuditLogChanges(logId: string): Promise<{
    success: boolean;
    data?: {
      changes_found: boolean;
      changes?: {
        added: AuditLogChange[];
        modified: AuditLogChange[];
        removed: AuditLogChange[];
      };
      old_record?: Record<string, any>;
      new_record?: Record<string, any>;
    };
    message?: string;
  }> {
    return this.getWithoutOrgId(`${api.audit_logs}/${logId}/changes`);
  }

  /**
   * Get aggregated metrics for audit logs
   *
   * Fetches server-side aggregated statistics matching current filter state.
   * More efficient than client-side computation for large datasets.
   *
   * Supported filters:
   * - Time range: hours parameter or start_time/end_time
   * - Action types: Comma-separated CREATE,UPDATE,DELETE
   * - Resource type: Single resource type
   * - Search: Full-text search across logs
   *
   * Response includes:
   * - total_actions: Total count matching filters
   * - by_action_type: Breakdown by CREATE/UPDATE/DELETE/VIEW/EXPORT
   * - by_resource_type: Breakdown by resource type
   * - time_range: Actual time range used for query
   *
   * @param params - Query parameters matching logs endpoint
   * @returns Promise with aggregated metrics
   * @throws Error if API request fails (caller should handle gracefully)
   *
   * @example
   * ```typescript
   * const metrics = await service.getAuditMetrics({
   *   hours: 24,
   *   action_types: 'CREATE,UPDATE'
   * });
   * console.log(metrics.data.total_actions); // 150
   * ```
   */
  public async getAuditMetrics(
    params: AuditMetricsParams = {},
  ): Promise<AuditMetricsResponse> {
    const queryParams = new URLSearchParams();
    if (params.hours) queryParams.append('hours', params.hours.toString());
    if (params.action_types)
      queryParams.append('action_types', params.action_types);
    if (params.resource_type)
      queryParams.append('resource_type', params.resource_type);
    if (params.search) queryParams.append('search', params.search);
    if (params.start_time) queryParams.append('start_time', params.start_time);
    if (params.end_time) queryParams.append('end_time', params.end_time);

    return this.getWithoutOrgId(
      api.audit_metrics + '?' + queryParams.toString(),
    );
  }

  /**
   * Get available resource types for filtering
   * These map to table_name values in the audit log
   */
  public getResourceTypes(): Array<{ label: string; value: string }> {
    // Values must match `audit.record_version.table_name` exactly —
    // the backend filter is a string-equality match. The previous
    // list (document/invoice/po/user/settings) never matched any
    // actual audit row, so the filter silently returned the
    // unfiltered list. Real table_names with audit rows in the last
    // 7 days: documents (~619k), preferences (~2.6k).
    //
    // Add new entries when more tables get a PostgreSQL audit
    // trigger; verify with:
    //   SELECT DISTINCT table_name FROM audit.record_version;
    return [
      { label: 'Documents', value: 'documents' },
      { label: 'Module changes', value: 'preferences' },
    ];
  }

  /**
   * Get available action types for filtering
   * These map to op values in the audit log (INSERT, UPDATE, DELETE)
   */
  public getActionTypes(): Array<{
    label: string;
    value: string;
    color: string;
    icon: string;
  }> {
    return [
      {
        label: 'Create',
        value: 'CREATE',
        color: 'positive',
        icon: 'add_circle',
      },
      { label: 'Update', value: 'UPDATE', color: 'primary', icon: 'edit' },
      { label: 'Delete', value: 'DELETE', color: 'negative', icon: 'delete' },
    ];
  }

  /**
   * Get time preset options for filtering
   */
  public getTimePresets(): Array<{
    label: string;
    value: string;
    hours: number;
  }> {
    return [
      { label: 'Last Hour', value: 'last_hour', hours: 1 },
      { label: 'Today', value: 'today', hours: 24 },
      { label: 'Last 7 Days', value: 'last_7_days', hours: 168 },
      { label: 'Last 30 Days', value: 'last_30_days', hours: 720 },
      { label: 'Custom', value: 'custom', hours: 0 },
    ];
  }
}
