<template>
  <q-dialog
    v-model="isOpen"
    persistent
    @show="onShow"
    @hide="onHide"
  >
    <q-card
      class="audit-detail-dialog"
      style="width: 1000px; max-width: 95vw; max-height: 90vh;"
    >
      <!-- Header with draggable toolbar -->
      <q-toolbar class="bg-primary text-white cursor-move">
        <q-icon name="history" size="24px" class="q-mr-sm" />
        <q-toolbar-title>
          <span class="text-weight-bold">Audit Log Details</span>
        </q-toolbar-title>
        <q-btn icon="close" flat round dense v-close-popup />
      </q-toolbar>

      <!-- Scrollable Content Area -->
      <q-card-section class="scroll" style="max-height: calc(90vh - 140px);">
        <!-- Loading State -->
        <div v-if="loading" class="loading-container">
          <q-spinner-dots size="50px" color="primary" />
          <div class="text-caption">Loading detailed changes...</div>
        </div>

        <!-- Error State -->
        <div v-else-if="loadError" class="error-container">
          <q-icon name="error_outline" size="40px" color="negative" />
          <div class="text-body1 text-negative">{{ loadError }}</div>
          <q-btn flat label="Retry" @click="fetchDetailedChanges" />
        </div>

        <!-- Content (when loaded) -->
        <template v-else-if="detailedChanges">
          <!-- User & Timestamp Section -->
          <div v-if="logEntry" class="detail-section q-mb-md">
            <div class="section-title">
              <q-icon name="person" class="q-mr-xs" />
              User Information
            </div>
            <div class="info-grid">
              <div class="info-row">
                <q-avatar size="40px" color="primary" text-color="white">
                  {{ getUserInitials(logEntry.user_name) }}
                </q-avatar>
                <div class="q-ml-sm">
                  <div class="text-weight-medium">{{ logEntry.user_name }}</div>
                  <div class="text-caption text-grey-7">{{ logEntry.user_email }}</div>
                </div>
              </div>
              <div class="info-row q-mt-sm">
                <span class="text-grey-7">Timestamp:</span>
                <span class="q-ml-xs text-weight-medium">
                  {{ formatAbsoluteTime(logEntry.timestamp) }}
                </span>
                <span class="q-ml-xs text-caption text-grey-7">
                  ({{ formatRelativeTime(logEntry.timestamp) }})
                </span>
              </div>
            </div>
          </div>

          <!-- Action & Resource Section -->
          <div v-if="logEntry" class="detail-section q-mb-md">
            <div class="section-title">
              <q-icon name="info" class="q-mr-xs" />
              Action Details
            </div>
            <div class="info-grid">
              <div class="info-row">
                <span class="text-grey-7">Action:</span>
                <q-badge
                  :color="getActionColor(logEntry.action)"
                  :label="logEntry.action"
                  class="q-ml-xs"
                >
                  <q-icon
                    :name="getActionIcon(logEntry.action)"
                    size="14px"
                    class="q-mr-xs"
                  />
                </q-badge>
              </div>
              <div class="info-row q-mt-sm">
                <span class="text-grey-7">Resource Type:</span>
                <span class="q-ml-xs text-weight-medium">
                  <q-icon
                    :name="getResourceIcon(logEntry.resource_type)"
                    size="18px"
                    class="q-mr-xs"
                  />
                  {{ logEntry.resource_type }}
                </span>
              </div>
              <div class="info-row q-mt-sm">
                <span class="text-grey-7">Resource Name:</span>
                <span class="q-ml-xs text-weight-medium">
                  {{ logEntry.resource_name || logEntry.resource_id }}
                </span>
              </div>
              <div class="info-row q-mt-sm" v-if="logEntry.ip_address">
                <span class="text-grey-7">IP Address:</span>
                <span class="q-ml-xs text-weight-medium">{{ logEntry.ip_address }}</span>
              </div>
            </div>
          </div>

          <!-- DIFF VIEW SECTION -->
          <div class="detail-section diff-section q-mb-md">
            <div class="section-title">
              <q-icon name="compare_arrows" class="q-mr-xs" />
              Field Changes - Diff View ({{ totalChangesCount }} changes)
            </div>

            <!-- Diff Container: Side-by-side comparison -->
            <div class="diff-container">
              <!-- Column Headers -->
              <div class="diff-header">
                <div class="diff-column-header old-header">
                  <q-icon name="remove_circle" color="negative" />
                  Old Value
                </div>
                <div class="diff-column-header new-header">
                  <q-icon name="add_circle" color="positive" />
                  New Value
                </div>
              </div>

              <!-- Diff Lines: Loop through changes -->
              <div class="diff-body">
                <!-- REMOVED fields (only in old) -->
                <div
                  v-for="change in detailedChanges.removed"
                  :key="'removed-' + change.field"
                  class="diff-line-group"
                >
                  <div class="diff-field-name">
                    {{ change.display_name || change.field }}
                    <q-btn
                      flat
                      dense
                      size="xs"
                      icon="content_copy"
                      @click="copyFieldName(change.field)"
                    >
                      <q-tooltip>Copy field name</q-tooltip>
                    </q-btn>
                  </div>
                  <div class="diff-line-pair">
                    <div class="diff-value removed">
                      <code>{{ formatValue(change.old_value) }}</code>
                      <q-btn
                        flat
                        dense
                        size="xs"
                        icon="content_copy"
                        @click="copyValue(change.old_value)"
                      >
                        <q-tooltip>Copy value</q-tooltip>
                      </q-btn>
                    </div>
                    <div class="diff-value empty">—</div>
                  </div>
                </div>

                <!-- MODIFIED fields (in both old and new) -->
                <div
                  v-for="change in detailedChanges.modified"
                  :key="'modified-' + change.field"
                  class="diff-line-group"
                >
                  <div class="diff-field-name">
                    {{ change.display_name || change.field }}
                    <q-btn
                      flat
                      dense
                      size="xs"
                      icon="content_copy"
                      @click="copyFieldName(change.field)"
                    >
                      <q-tooltip>Copy field name</q-tooltip>
                    </q-btn>
                  </div>
                  <div class="diff-line-pair">
                    <div class="diff-value modified-old">
                      <code>{{ formatValue(change.old_value) }}</code>
                      <q-btn
                        flat
                        dense
                        size="xs"
                        icon="content_copy"
                        @click="copyValue(change.old_value)"
                      >
                        <q-tooltip>Copy old value</q-tooltip>
                      </q-btn>
                    </div>
                    <div class="diff-value modified-new">
                      <code>{{ formatValue(change.new_value) }}</code>
                      <q-btn
                        flat
                        dense
                        size="xs"
                        icon="content_copy"
                        @click="copyValue(change.new_value)"
                      >
                        <q-tooltip>Copy new value</q-tooltip>
                      </q-btn>
                    </div>
                  </div>
                </div>

                <!-- ADDED fields (only in new) -->
                <div
                  v-for="change in detailedChanges.added"
                  :key="'added-' + change.field"
                  class="diff-line-group"
                >
                  <div class="diff-field-name">
                    {{ change.display_name || change.field }}
                    <q-btn
                      flat
                      dense
                      size="xs"
                      icon="content_copy"
                      @click="copyFieldName(change.field)"
                    >
                      <q-tooltip>Copy field name</q-tooltip>
                    </q-btn>
                  </div>
                  <div class="diff-line-pair">
                    <div class="diff-value empty">—</div>
                    <div class="diff-value added">
                      <code>{{ formatValue(change.new_value) }}</code>
                      <q-btn
                        flat
                        dense
                        size="xs"
                        icon="content_copy"
                        @click="copyValue(change.new_value)"
                      >
                        <q-tooltip>Copy value</q-tooltip>
                      </q-btn>
                    </div>
                  </div>
                </div>

                <!-- No changes message -->
                <div v-if="totalChangesCount === 0" class="no-changes">
                  <q-icon name="info" size="32px" color="grey-5" />
                  <div class="text-body2 text-grey-7">
                    No field changes detected
                  </div>
                </div>
              </div>
            </div>
          </div>

          <!-- Database Metadata -->
          <div v-if="logEntry && logEntry.metadata" class="detail-section">
            <div class="section-title">
              <q-icon name="storage" class="q-mr-xs" />
              Database Metadata
            </div>
            <div class="info-grid">
              <div class="info-row">
                <span class="text-grey-7">Table:</span>
                <span class="q-ml-xs text-weight-medium">
                  {{ logEntry.metadata.table_schema }}.{{ logEntry.metadata.table_name }}
                </span>
              </div>
              <div class="info-row q-mt-sm" v-if="logEntry.metadata.record_version">
                <span class="text-grey-7">Record Version:</span>
                <span class="q-ml-xs text-weight-medium">
                  {{ logEntry.metadata.record_version }}
                </span>
              </div>
            </div>
          </div>
        </template>
      </q-card-section>

      <!-- Footer Actions -->
      <q-card-actions align="between" class="q-pa-md bg-grey-1">
        <!-- Left: Navigation buttons -->
        <div class="navigation-buttons row items-center">
          <q-btn
            outline
            color="primary"
            icon="navigate_before"
            label="Previous"
            :disable="!hasPrevious"
            @click="navigateToPrevious"
          />
          <span class="q-mx-sm text-caption text-grey-7">
            {{ currentIndex + 1 }} of {{ totalLogs }}
          </span>
          <q-btn
            outline
            color="primary"
            icon-right="navigate_next"
            label="Next"
            :disable="!hasNext"
            @click="navigateToNext"
          />
        </div>

        <!-- Right: Export and close -->
        <div class="action-buttons row q-gutter-sm">
          <q-btn
            outline
            color="primary"
            icon="download"
            label="Export JSON"
            @click="exportAsJson"
          />
          <q-btn
            flat
            color="primary"
            label="Close"
            v-close-popup
          />
        </div>
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue';
import { notify } from 'src/components/notifications/notify';
import { formatDistanceToNow, format, parseISO } from 'date-fns';
import AuditTrailApiService, { type AuditLogEntry, type AuditLogChange } from 'src/services/auditTrail/AuditTrailApiService';

// Type definitions for API response
interface ChangeDetail extends AuditLogChange {
  display_name: string;
  change_type: 'creation' | 'modification' | 'deletion';
}

// Props
interface Props {
  modelValue: boolean;
  logEntry: AuditLogEntry | null;
  allLogs?: AuditLogEntry[];
}

const props = withDefaults(defineProps<Props>(), {
  modelValue: false,
  logEntry: null,
  allLogs: undefined,
});

// Emits
const emit = defineEmits<{
  'update:modelValue': [value: boolean];
  'navigate': [logEntry: AuditLogEntry];
}>();

// State
const isOpen = computed({
  get: () => props.modelValue,
  set: (value) => emit('update:modelValue', value),
});

// New state for API data
const loading = ref(false);
const loadError = ref<string | null>(null);
const detailedChanges = ref<{
  added: AuditLogChange[];
  modified: AuditLogChange[];
  removed: AuditLogChange[];
} | null>(null);
const oldRecord = ref<any>(null);
const newRecord = ref<any>(null);

// Navigation computed properties
const currentIndex = computed(() => {
  if (!props.allLogs || !props.logEntry) return -1;
  return props.allLogs.findIndex(log => log.id === props.logEntry.id);
});

const totalLogs = computed(() => props.allLogs?.length || 0);

const hasPrevious = computed(() => currentIndex.value > 0);
const hasNext = computed(() => currentIndex.value < totalLogs.value - 1);

// Total changes count
const totalChangesCount = computed(() => {
  if (!detailedChanges.value) return 0;
  return (
    detailedChanges.value.added.length +
    detailedChanges.value.modified.length +
    detailedChanges.value.removed.length
  );
});

// Methods
const fetchDetailedChanges = async () => {
  if (!props.logEntry?.id) return;

  // If we already have the record/old_record in the log entry, use them to compute diff locally
  // This avoids an extra API call and fixes the issue where the API might return error
  if (props.logEntry.record || props.logEntry.old_record) {
    loading.value = true;
    try {
      // Small delay to simulate async feeling / UI responsiveness
      await new Promise(resolve => setTimeout(resolve, 100));
      
      const oldRec = props.logEntry.old_record || null;
      const newRec = props.logEntry.record || null;
      
      detailedChanges.value = computeDiff(oldRec, newRec);
      oldRecord.value = oldRec;
      newRecord.value = newRec;
      return;
    } catch (e) {
      console.warn('Local diff computation failed, falling back to API', e);
    } finally {
      loading.value = false;
    }
  }

  loading.value = true;
  loadError.value = null;

  try {
    const auditService = new AuditTrailApiService();
    const response = await auditService.getAuditLogChanges(props.logEntry.id);

    if (response.success) {
      // If changes are provided (pre-computed by backend)
      if (response.data?.changes_found && response.data?.changes) {
        detailedChanges.value = response.data.changes;
        oldRecord.value = response.data.old_record;
        newRecord.value = response.data.new_record;
      }
      // If backend sent changes_found: false but has empty change arrays, use them
      else if (response.data?.changes) {
        detailedChanges.value = response.data.changes;
        oldRecord.value = response.data.old_record || null;
        newRecord.value = response.data.new_record || null;
      }
      // If API returns no changes found but records are available, compute diff locally
      else if (response.data?.old_record || response.data?.new_record) {
        detailedChanges.value = computeDiff(response.data.old_record, response.data.new_record);
        oldRecord.value = response.data.old_record;
        newRecord.value = response.data.new_record;
      }
      // No data at all
      else {
        loadError.value = 'No detailed change data available';
      }
    } else {
      loadError.value = 'Failed to load detailed changes';
    }
  } catch (error: any) {
    console.error('Failed to fetch detailed changes:', error);
    // ApiClient.handleError throws error.response.data directly, so check error.message first
    // Also check nested response structures for axios errors
    const apiMessage = error?.message || error?.response?.data?.message || error?.data?.message;
    loadError.value = apiMessage || 'Failed to load detailed changes. Please try again.';
  } finally {
    loading.value = false;
  }
};

const isEqual = (a: any, b: any): boolean => {
  if (a === b) return true;
  if (a === null || a === undefined || b === null || b === undefined) {
    return a === b;
  }
  if (typeof a === 'object' && typeof b === 'object') {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    // Deep comparison could be expensive, but for JSON fields it's usually necessary
    // Using JSON stringify for simplicity as these are JSON fields
    return JSON.stringify(a) === JSON.stringify(b);
  }
  return String(a) === String(b);
};

const computeDiff = (oldData: any, newData: any) => {
  const added: ChangeDetail[] = [];
  const modified: ChangeDetail[] = [];
  const removed: ChangeDetail[] = [];

  const oldObj = oldData || {};
  const newObj = newData || {};

  const allKeys = new Set([...Object.keys(oldObj), ...Object.keys(newObj)]);

  allKeys.forEach(key => {
    const oldVal = oldObj[key];
    const newVal = newObj[key];

    // Skip internal fields if necessary? For now keep all.
    
    if (oldVal === undefined && newVal !== undefined) {
      added.push({
        field: key,
        old_value: null,
        new_value: newVal,
        display_name: key,
        change_type: 'creation'
      });
    } else if (oldVal !== undefined && newVal === undefined) {
      removed.push({
        field: key,
        old_value: oldVal,
        new_value: null,
        display_name: key,
        change_type: 'deletion'
      });
    } else if (!isEqual(oldVal, newVal)) {
      modified.push({
        field: key,
        old_value: oldVal,
        new_value: newVal,
        display_name: key,
        change_type: 'modification'
      });
    }
  });

  return { added, modified, removed };
};

const onShow = async () => {
  console.log('Audit detail dialog opened');
  await fetchDetailedChanges();
};

const onHide = () => {
  console.log('Audit detail dialog closed');
};

const getUserInitials = (name: string): string => {
  return name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .toUpperCase()
    .substring(0, 2);
};

const formatRelativeTime = (timestamp: string): string => {
  try {
    return formatDistanceToNow(parseISO(timestamp), { addSuffix: true });
  } catch {
    return timestamp;
  }
};

const formatAbsoluteTime = (timestamp: string): string => {
  try {
    return format(parseISO(timestamp), 'MMM dd, yyyy HH:mm:ss');
  } catch {
    return timestamp;
  }
};

const formatValue = (value: any): string => {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'object') {
    try {
      return JSON.stringify(value, null, 2);
    } catch {
      return String(value);
    }
  }
  return String(value);
};

const getActionColor = (action: string): string => {
  const colors: Record<string, string> = {
    CREATE: 'positive',
    UPDATE: 'primary',
    DELETE: 'negative',
    VIEW: 'grey-7',
    EXPORT: 'orange',
  };
  return colors[action] || 'grey';
};

const getActionIcon = (action: string): string => {
  const icons: Record<string, string> = {
    CREATE: 'add_circle',
    UPDATE: 'edit',
    DELETE: 'delete',
    VIEW: 'visibility',
    EXPORT: 'download',
  };
  return icons[action] || 'info';
};

const getResourceIcon = (resourceType: string): string => {
  const icons: Record<string, string> = {
    document: 'description',
    invoice: 'receipt',
    po: 'shopping_cart',
    user: 'person',
    settings: 'settings',
  };
  return icons[resourceType] || 'folder';
};

const copyFieldName = (fieldName: string) => {
  navigator.clipboard.writeText(fieldName);
  notify.success('Field name copied', { description: fieldName });
};

const copyValue = (value: any) => {
  const textValue = formatValue(value);
  navigator.clipboard.writeText(textValue);
  notify.success('Value copied to clipboard');
};

const exportAsJson = () => {
  if (!props.logEntry) return;

  const dataStr = JSON.stringify(props.logEntry, null, 2);
  const dataBlob = new Blob([dataStr], { type: 'application/json' });
  const url = URL.createObjectURL(dataBlob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `audit-log-${props.logEntry.id}-${format(new Date(), 'yyyy-MM-dd-HHmmss')}.json`;
  link.click();
  URL.revokeObjectURL(url);

  notify.success('Audit log exported');
};

const navigateToPrevious = () => {
  if (hasPrevious.value && props.allLogs) {
    emit('navigate', props.allLogs[currentIndex.value - 1]);
  }
};

const navigateToNext = () => {
  if (hasNext.value && props.allLogs) {
    emit('navigate', props.allLogs[currentIndex.value + 1]);
  }
};

// Keyboard shortcuts
const handleKeydown = (event: KeyboardEvent) => {
  if (!isOpen.value) return;

  switch (event.key) {
    case 'Escape':
      isOpen.value = false;
      break;
    case 'ArrowLeft':
      if (hasPrevious.value) navigateToPrevious();
      break;
    case 'ArrowRight':
      if (hasNext.value) navigateToNext();
      break;
  }
};

// Watch for log entry changes and refetch data
watch(() => props.logEntry?.id, async (newId, oldId) => {
  if (newId && newId !== oldId && isOpen.value) {
    await fetchDetailedChanges();
  }
});

onMounted(() => {
  document.addEventListener('keydown', handleKeydown);
});

onBeforeUnmount(() => {
  document.removeEventListener('keydown', handleKeydown);
});
</script>

<style lang="scss" scoped>
/* Dark-mode palette tokens. Quasar adds `body.body--dark` to <body>
 * when dark mode is active; we use it as a parent selector throughout
 * this stylesheet so the dialog's panels, diff boxes and badges stay
 * legible without manual @media queries.
 *
 * Saturated diff backgrounds (red/green/yellow/blue) are softened on
 * dark surfaces — the original light pastels were near-white and
 * burned the eye on a dark backdrop. */
$dark-section-bg: #1f2128;
$dark-section-border: #2e3038;
$dark-section-title: #e8e9ed;
$dark-diff-bg: #181a20;

.audit-detail-dialog {
  border-radius: 8px;

  .detail-section {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 16px;
    background: white;

    body.body--dark & {
      background: $dark-section-bg;
      border-color: $dark-section-border;
      color: #cfd2da;
    }

    .section-title {
      font-size: 16px;
      font-weight: 600;
      color: #1a1a1a;
      margin-bottom: 12px;
      display: flex;
      align-items: center;

      body.body--dark & {
        color: $dark-section-title;
      }
    }

    .info-grid {
      .info-row {
        display: flex;
        align-items: center;
        padding: 4px 0;
      }
    }
  }

  .diff-section {
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    padding: 16px;
    background: #fafafa;

    body.body--dark & {
      background: $dark-diff-bg;
      border-color: $dark-section-border;
    }
  }

  .diff-container {
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  .diff-header {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    margin-bottom: 12px;

    .diff-column-header {
      font-weight: 600;
      padding: 8px 12px;
      border-radius: 4px;
      display: flex;
      align-items: center;
      gap: 8px;

      &.old-header {
        background: #ffebee;
        color: #c62828;
        border: 1px solid #ef9a9a;

        body.body--dark & {
          background: rgba(239, 83, 80, 0.18);
          color: #ff8a80;
          border-color: rgba(239, 83, 80, 0.45);
        }
      }

      &.new-header {
        background: #e8f5e9;
        color: #2e7d32;
        border: 1px solid #a5d6a7;

        body.body--dark & {
          background: rgba(102, 187, 106, 0.18);
          color: #a5d6a7;
          border-color: rgba(102, 187, 106, 0.45);
        }
      }
    }
  }

  .diff-body {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .diff-line-group {
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    overflow: hidden;

    body.body--dark & {
      border-color: $dark-section-border;
    }

    .diff-field-name {
      background: #f5f5f5;
      padding: 8px 12px;
      font-weight: 600;
      border-bottom: 1px solid #e0e0e0;
      display: flex;
      align-items: center;
      justify-content: space-between;

      body.body--dark & {
        background: #24262e;
        border-bottom-color: $dark-section-border;
        color: #cfd2da;
      }
    }

    .diff-line-pair {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1px;
      background: #e0e0e0; // Gap color

      body.body--dark & {
        background: $dark-section-border;
      }

      .diff-value {
        padding: 12px;
        display: flex;
        align-items: flex-start;
        justify-content: space-between;
        min-height: 50px;

        code {
          flex: 1;
          font-family: 'Monaco', 'Menlo', 'Courier New', monospace;
          font-size: 13px;
          white-space: pre-wrap;
          word-break: break-word;
        }

        &.removed {
          background: #ffebee;
