<script setup lang="ts">
import { notify } from 'src/components/notifications/notify';
import { ref, computed, onMounted, onBeforeUnmount, reactive } from 'vue';
import { toBoolPreference } from 'src/utils/preferenceBool';

// Define component name for error handling
defineOptions({
  name: 'AccessAudit',
});
import { formatDistanceToNow, format, parseISO } from 'date-fns';
import { useQuasar } from 'quasar';
import AuditTrailApiService, {
  AuditLogEntry,
  PaginationInfo,
  AuditMetricsResponse,
} from 'src/services/auditTrail/AuditTrailApiService';
import AuditLogDetailDialog from 'src/components/AuditLogDetailDialog.vue';
import AuditTrailDisabledDialog from 'src/components/AuditTrailDisabledDialog.vue';
import preferencesService from 'src/services/preferences/preferencesService';

const $q = useQuasar();
const auditTrailApiService = new AuditTrailApiService();

// State for tracking previous values
const previousValues = ref({
  selectedTimePreset: '',
  selectedActionTypes: [],
  selectedResourceTypes: [],
  searchTerm: '',
});
const loading = ref(false);
const logs = ref<AuditLogEntry[]>([]);
const displayedLogs = ref<AuditLogEntry[]>([]);
const selectedTimePreset = ref('last_hour');
const customStartDate = ref('');
const customEndDate = ref('');
const auditTrailEnabled = ref(false);
const togglingAuditTrail = ref(false);
const showDisabledDialog = ref(false);

// Flag to suppress global error handler during expected API failures
(window as any).__suppressAuditErrorHandler = false;

const selectedActionTypes = ref<string[]>(['CREATE', 'UPDATE', 'DELETE']);
const selectedResourceTypes = ref<string[]>([]);
const searchTerm = ref('');
const autoRefresh = ref(false);
const autoRefreshInterval = ref<ReturnType<typeof setInterval> | null>(null);
const expandedRows = reactive<Record<string, boolean>>({});

// Detail dialog state
const showDetailDialog = ref(false);
const selectedLogEntry = ref<AuditLogEntry | null>(null);

// API pagination state (from backend response)
const apiPagination = ref<PaginationInfo | null>(null);

// Metrics state
const metricsData = ref<AuditMetricsResponse['data'] | null>(null);
const loadingMetrics = ref(false);
const metricsError = ref(false);

/**
 * Statistics with server-side metrics + client-side fallback
 *
 * Priority:
 * 1. Server-side metrics (if available and no error)
 * 2. Client-side computation (fallback if metrics API fails)
 *
 * Note: VIEW and EXPORT actions are intentionally ignored
 * (removed from UI in commit 6db830690c but backend still returns them)
 */
const stats = computed(() => {
  // Use server-side metrics if available
  if (metricsData.value && !metricsError.value) {
    return {
      total: metricsData.value.total_actions,
      create: metricsData.value.by_action_type.CREATE,
      update: metricsData.value.by_action_type.UPDATE,
      delete: metricsData.value.by_action_type.DELETE,
      // VIEW and EXPORT intentionally ignored (not displayed in UI)
    };
  }

  // Fallback to client-side computation
  const total = displayedLogs.value.length;
  const create = displayedLogs.value.filter(
    (log) => log.action === 'CREATE',
  ).length;
  const update = displayedLogs.value.filter(
    (log) => log.action === 'UPDATE',
  ).length;
  const del = displayedLogs.value.filter(
    (log) => log.action === 'DELETE',
  ).length;
  return { total, create, update, delete: del };
});

// Options
const timePresetOptions = auditTrailApiService.getTimePresets();
const actionTypeOptions = auditTrailApiService.getActionTypes();
const resourceTypeOptions = auditTrailApiService.getResourceTypes();

// Table columns
const columns = [
  {
    name: 'timestamp',
    label: 'Timestamp',
    field: 'timestamp',
    align: 'left' as const,
    sortable: true,
    style: 'width: 150px',
  },
  {
    name: 'user',
    label: 'User',
    field: 'user_name',
    align: 'left' as const,
    sortable: true,
    style: 'width: 200px',
  },
  {
    name: 'action',
    label: 'Action',
    field: 'action',
    align: 'center' as const,
    sortable: true,
    style: 'width: 100px',
  },
  {
    // Surface the audit-table category (documents / preferences /
    // future tables) as its own column so it's visible WITHOUT
    // expanding the row, AND so a user who filtered on a type can
    // immediately see "yes, the list now shows only this type".
    name: 'resource_type',
    label: 'Type',
    field: 'resource_type',
    align: 'left' as const,
    sortable: true,
    style: 'width: 130px',
  },
  {
    name: 'resource',
    label: 'Resource',
    field: 'resource_name',
    align: 'left' as const,
    sortable: true,
    style: 'width: 200px',
  },

  {
    name: 'expand',
    label: '',
    field: 'expand',
    align: 'center' as const,
    sortable: false,
    style: 'width: 80px', // Wider to accommodate two buttons
  },
];

const pagination = ref({
  sortBy: 'timestamp',
  descending: true,
  page: 1,
  rowsPerPage: 25,
  rowsNumber: 0,
});

// Methods

const fetchAuditTrailPreference = async () => {
  try {
    const value = await preferencesService.getOrgPreference('AUDIT_TRAIL');
    // toBoolPreference: kept in lockstep with the backend's falsy-string set,
    // not a strict === 'true' check that misses "1"/"yes"/"on" etc.
    auditTrailEnabled.value = toBoolPreference(value);
  } catch (error) {
    console.error('Failed to fetch audit trail preference:', error);
  }
};

const toggleAuditTrail = async (newValue: boolean) => {
  try {
    togglingAuditTrail.value = true;
    const response = await preferencesService.setOrgPreference(
      'AUDIT_TRAIL',
      newValue,
    );
    if (response.success) {
      auditTrailEnabled.value = newValue;
      notify.success(`Audit Trail ${newValue ? 'Enabled' : 'Disabled'}`, {
        description: 'Organization preference updated successfully',
      });
    } else {
      // Revert on failure
      auditTrailEnabled.value = !newValue;
      notify.error('Failed to update Access Audit preference', response.error);
    }
  } catch (error) {
    // Revert on error
    auditTrailEnabled.value = !newValue;
    console.error('Error toggling audit trail:', error);
    notify.error('An unexpected error occurred');
  } finally {
    togglingAuditTrail.value = false;
  }
};

/**
 * Check if we should show the audit trail disabled popup.
 * Shows only once per browser session using sessionStorage.
 */
const checkAndShowDisabledPopup = () => {
  // Don't show if already shown this session
  const alreadyShown = sessionStorage.getItem('audit_trail_popup_shown');
  if (alreadyShown === 'true') {
    return;
  }

  // Show if audit trail is disabled or null (treated as disabled)
  if (!auditTrailEnabled.value) {
    showDisabledDialog.value = true;
    sessionStorage.setItem('audit_trail_popup_shown', 'true');
  }
};

/**
 * Handle "Enable Audit Trail" button click from popup
 */
const handleEnableFromPopup = async () => {
  await toggleAuditTrail(true);
  showDisabledDialog.value = false;
};

/**
 * Handle "Close" button click from popup
 */
const handleClosePopup = () => {
  showDisabledDialog.value = false;
};

const loadAuditLogs = async () => {
  loading.value = true;

  // Set flag to suppress global error handler
  (window as any).__suppressAuditErrorHandler = true;

  // Wrap everything in try-catch to prevent ANY error from bubbling up
  try {
    try {
      const params = buildApiParams();
      const response = await auditTrailApiService.getAuditLogs(params);
      const responseData = (response?.data ?? {}) as {
        logs?: any[];
        total_count?: number;
        pagination?: any;
      };
      const nextLogs = Array.isArray(responseData.logs)
        ? responseData.logs
        : [];
      logs.value = nextLogs;
      displayedLogs.value = nextLogs;
      pagination.value.rowsNumber = Number(
        responseData.total_count ?? nextLogs.length,
      );

      // Capture API pagination info if available
      if (responseData.pagination) {
        apiPagination.value = responseData.pagination;
      }
    } catch (apiError) {
      // API call failed - handle gracefully without propagating error
      console.error('Failed to load audit logs:', apiError);

      // Clear existing data
      logs.value = [];
      displayedLogs.value = [];
      pagination.value.rowsNumber = 0;
      apiPagination.value = null;

      // Show user-friendly error notification (only once per session)
      if (!sessionStorage.getItem('audit_logs_error_shown')) {
        notify.warning('Audit logs endpoint not available', {
          description:
            'The audit logs feature is currently being configured on the backend.',
        });
        sessionStorage.setItem('audit_logs_error_shown', 'true');
      }
    }
  } catch (outerError) {
    // Catch ANY unexpected error to prevent reload loop
    console.error('Unexpected error in loadAuditLogs:', outerError);
    logs.value = [];
    displayedLogs.value = [];
    pagination.value.rowsNumber = 0;
    apiPagination.value = null;
  } finally {
    loading.value = false;
    // Clear flag after operation completes
    (window as any).__suppressAuditErrorHandler = false;
  }
};

const buildApiParams = () => {
  const params: Record<string, string | number | undefined> = {};

  // Time range - use 'hours' param for presets (simpler API call)
  if (selectedTimePreset.value !== 'custom') {
    const preset = timePresetOptions.find(
      (p) => p.value === selectedTimePreset.value,
    );
    const hours = preset?.hours || 1;
    // Use 'hours' parameter for simpler API call
    params.hours = hours;
  } else if (customStartDate.value && customEndDate.value) {
    // For custom dates, use explicit start/end times
    params.start_time = new Date(customStartDate.value).toISOString();
    params.end_time = new Date(customEndDate.value).toISOString();
  }

  // Filters - always send action_types, even if empty (backend handles empty as "no filter")
  params.action_types = selectedActionTypes.value.join(',');
  // Always send resource_types, even if empty (backend handles empty as "no filter")
  params.resource_types = selectedResourceTypes.value.join(',');
  if (searchTerm.value) {
    params.search = searchTerm.value;
  }

  // Pagination - use page_size and offset-based pagination
  params.page_size = pagination.value.rowsPerPage;
  params.page = pagination.value.page;

  // Use next_offset from API response if available and navigating forward
  // Otherwise calculate offset from page number
  if (
    apiPagination.value?.next_offset !== null &&
    apiPagination.value?.current_page === pagination.value.page - 1
  ) {
    // Navigating to next page, use the provided next_offset
    params.offset = apiPagination.value.next_offset;
  } else {
    // Calculate offset manually (for first page or jumping pages)
    params.offset = (pagination.value.page - 1) * pagination.value.rowsPerPage;
  }

  return params;
};

/**
 * Build query parameters for metrics API
 *
 * Mirrors buildApiParams but excludes pagination parameters
 * (metrics endpoint doesn't paginate, just aggregates)
 */
const buildMetricsParams = () => {
  const params: Record<string, string | number | undefined> = {};

  // Time range - use 'hours' param for presets
  if (selectedTimePreset.value !== 'custom') {
    const preset = timePresetOptions.find(
      (p) => p.value === selectedTimePreset.value,
    );
    const hours = preset?.hours || 1;
    params.hours = hours;
  } else if (customStartDate.value && customEndDate.value) {
    // For custom dates, use explicit start/end times
    params.start_time = new Date(customStartDate.value).toISOString();
    params.end_time = new Date(customEndDate.value).toISOString();
  }

  // Filters - always send action_types, even if empty
  params.action_types = selectedActionTypes.value.join(',');

  // Send resource_types only if selected (singular for metrics API)
  if (selectedResourceTypes.value.length > 0) {
    // Metrics API expects singular resource_type (first selected)
    params.resource_type = selectedResourceTypes.value[0];
  }

  if (searchTerm.value) {
    params.search = searchTerm.value;
  }

  return params;
};

/**
 * Load audit metrics from server
 *
 * Fetches aggregated metrics matching current filter state.
 * Runs independently from log loading for better performance.
 * Falls back to client-side computation on error.
 */
const loadAuditMetrics = async () => {
  // Don't load metrics if audit trail is disabled
  if (!auditTrailEnabled.value) {
    metricsData.value = null;
    return;
  }

  loadingMetrics.value = true;
  metricsError.value = false;

  try {
    const params = buildMetricsParams();
    const response = await auditTrailApiService.getAuditMetrics(params);

    if (response.success) {
      metricsData.value = response.data;
    } else {
      console.warn('Metrics API returned success=false, using fallback');
      metricsError.value = true;
    }
  } catch (error) {
    console.error('Failed to load audit metrics:', error);
    metricsError.value = true;

    // Show user-friendly notification (only once per session)
    if (!sessionStorage.getItem('audit_metrics_error_shown')) {
      notify.info('Using client-side metrics calculation', {
        description: 'Server metrics temporarily unavailable',
        duration: 3000,
      });
      sessionStorage.setItem('audit_metrics_error_shown', 'true');
    }
  } finally {
    loadingMetrics.value = false;
  }
};

const applyTimePreset = () => {
  // Store previous value and show change notification
  const previousValue = previousValues.value.selectedTimePreset;
  const currentValue = selectedTimePreset.value;

  if (previousValue !== currentValue && previousValue !== '') {
    const previousLabel =
      timePresetOptions.find((opt) => opt.value === previousValue)?.label ||
      previousValue;
    const currentLabel =
      timePresetOptions.find((opt) => opt.value === currentValue)?.label ||
      currentValue;

    notify.success('Time filter changed', {
      description: `From "${previousLabel}" to "${currentLabel}"`,
      duration: 3000,
    });
  }

  // Update previous value
  previousValues.value.selectedTimePreset = currentValue;

  // Reset pagination to first page when time filter changes
  pagination.value.page = 1;

  try {
    // Load logs and metrics in parallel
    Promise.all([loadAuditLogs(), loadAuditMetrics()]).catch((error) => {
      console.error('Error in applyTimePreset:', error);
    });
  } catch (syncError) {
    // Catch synchronous errors that might occur before the async call
    console.error('Synchronous error in applyTimePreset:', syncError);
  }
};

const applyCustomDateRange = () => {
  if (customStartDate.value && customEndDate.value) {
    // Reset pagination for custom date range
    pagination.value.page = 1;

    // Load logs and metrics in parallel
    Promise.all([loadAuditLogs(), loadAuditMetrics()]).catch((error) => {
      console.error('Error in applyCustomDateRange:', error);
    });
  }
};

const toggleActionType = (action: string) => {
  const previousArray = [...selectedActionTypes.value];
  const index = selectedActionTypes.value.indexOf(action);

  if (index > -1) {
    selectedActionTypes.value.splice(index, 1);
  } else {
    selectedActionTypes.value.push(action);
  }

  // Show notification only if this is a user action (not initial load)
  if (
    previousValues.value.selectedActionTypes.length > 0 ||
    (previousValues.value.selectedActionTypes.length === 0 &&
      selectedActionTypes.value.length > 0)
  ) {
    const actionInfo = actionTypeOptions.find((opt) => opt.value === action);
    const actionLabel = actionInfo?.label || action;
    const isAdded = index === -1;

    notify.info('Filter updated', {
      description: `${isAdded ? 'Added' : 'Removed'} action filter: ${actionLabel}`,
      duration: 1500,
    });
  }

  previousValues.value.selectedActionTypes = [...selectedActionTypes.value];
  pagination.value.page = 1;

  // Load logs and metrics in parallel
  Promise.all([loadAuditLogs(), loadAuditMetrics()]).catch((error) => {
    console.error('Error in toggleActionType:', error);
  });
};

const onResourceTypeChange = () => {
  // Check for changes
  const prev = previousValues.value.selectedResourceTypes;
  const curr = selectedResourceTypes.value;

  if (JSON.stringify(prev) !== JSON.stringify(curr)) {
    // Determine what changed
    const added = curr.filter((x) => !prev.includes(x));
    const removed = prev.filter((x) => !curr.includes(x));

    let caption = '';
    if (added.length > 0) {
      const label =
        resourceTypeOptions.find((opt) => opt.value === added[0])?.label ||
        added[0];
      caption = `Added: ${label}${added.length > 1 ? ` (+${added.length - 1} more)` : ''}`;
    } else if (removed.length > 0) {
      const label =
        resourceTypeOptions.find((opt) => opt.value === removed[0])?.label ||
        removed[0];
      caption = `Removed: ${label}${removed.length > 1 ? ` (+${removed.length - 1} more)` : ''}`;
    }

    notify.info('Resource filter updated', {
      description: caption,
      duration: 1500,
    });

    previousValues.value.selectedResourceTypes = [...curr];
    pagination.value.page = 1;

    // Load logs and metrics in parallel
    Promise.all([loadAuditLogs(), loadAuditMetrics()]).catch(console.error);
  }
};

const onSearchChange = () => {
  // Store previous value and show change notification
  const previousValue = previousValues.value.searchTerm;
  const currentValue = searchTerm.value;

  // Show notification only if this is a user action (not initial load or clear)
  if (previousValue !== '' && currentValue !== previousValue) {
    if (currentValue) {
      notify.success('Search applied', {
        description: `Searching for: "${currentValue}"`,
        duration: 2500,
      });
    } else {
      notify.info('Search cleared', { description: 'Showing all results' });
    }
  } else if (previousValue === '' && currentValue) {
    // First search after page load
    notify.success('Search applied', {
      description: `Searching for: "${currentValue}"`,
      duration: 2500,
    });
  }

  // Update previous value
  previousValues.value.searchTerm = currentValue;

  // Reset pagination when search changes
  pagination.value.page = 1;

  // Load logs and metrics in parallel
  Promise.all([loadAuditLogs(), loadAuditMetrics()]).catch((error) => {
    console.error('Error in onSearchChange:', error);
  });
};

const onPaginationChange = (props: any) => {
  const nextPagination = props?.pagination ?? props;

  if (!nextPagination || typeof nextPagination !== 'object') {
    return;
  }

  const normalizedPagination = {
    ...pagination.value,
    ...nextPagination,
  };

  // Only load new data if the page actually changes
  if (
    normalizedPagination.page !== pagination.value.page ||
    normalizedPagination.rowsPerPage !== pagination.value.rowsPerPage
  ) {
    pagination.value = normalizedPagination;

    // Load data for the new page
    try {
      loadAuditLogs();
    } catch (error) {
      console.error('Error in onPaginationChange:', error);
    }
  } else {
    // Just update the pagination state without reloading data
    pagination.value = normalizedPagination;
  }
};

// Formatting helpers
const formatRelativeTime = (timestamp: string) => {
  try {
    return formatDistanceToNow(parseISO(timestamp), { addSuffix: true });
  } catch {
    return timestamp;
  }
};

const formatAbsoluteTime = (timestamp: string) => {
  try {
    return format(parseISO(timestamp), 'MMM dd, yyyy HH:mm:ss');
  } catch {
    return timestamp;
  }
};

const getUserInitials = (name: string) => {
  return name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .toUpperCase()
    .substring(0, 2);
};

const getActionColor = (action: string) => {
  const colors: Record<string, string> = {
    CREATE: 'positive',
    UPDATE: 'primary',
    DELETE: 'negative',
    VIEW: 'grey-7',
    EXPORT: 'orange',
  };
  return colors[action] || 'grey';
};

const getActionIcon = (action: string) => {
  const icons: Record<string, string> = {
    CREATE: 'add_circle',
    UPDATE: 'edit',
    DELETE: 'delete',
    VIEW: 'visibility',
    EXPORT: 'download',
  };
  return icons[action] || 'info';
};

const getActionLabel = (action: string) => {
  const option = actionTypeOptions.find((opt) => opt.value === action);
  return option ? option.label : action;
};

const getResourceIcon = (resourceType: string) => {
  // Module-toggles + other org-level preferences land here as
  // resource_type === "preferences" — a switch icon makes them
  // visually distinct from documents / invoices in the audit list.
  const icons: Record<string, string> = {
    documents: 'description',
    document: 'description',
    invoice: 'receipt',
    po: 'shopping_cart',
    user: 'person',
    settings: 'settings',
    preferences: 'toggle_on',
  };
  return icons[resourceType] || 'folder';
};

/** Map a raw audit table_name to the same business-friendly label
 *  the resource-type filter uses. Keeps both UIs in sync — if we
 *  rename "preferences" → "Module changes" in the filter, the table
 *  column reads it the same way. Falls back to the raw value when
 *  no mapping exists so new tables still render without a code change. */
const getResourceTypeLabel = (resourceType: string): string => {
  const option = resourceTypeOptions.find((opt) => opt.value === resourceType);
  return option ? option.label : resourceType;
};

/** Color the resource-type chip so the eye can scan documents vs
 *  preferences at a glance. Same teal accent the rest of DOCB-12164
 *  uses for module-related UI; documents stay neutral primary. */
const getResourceTypeColor = (resourceType: string): string => {
  if (resourceType === 'preferences') return 'teal';
  if (resourceType === 'documents') return 'primary';
  return 'grey-7';
};

const formatValue = (value: string | number | boolean | null): string => {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
};

const exportLogs = () => {
  try {
    const dataStr = JSON.stringify(displayedLogs.value, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `audit-trail-${format(new Date(), 'yyyy-MM-dd-HHmmss')}.json`;
    link.click();
    URL.revokeObjectURL(url);

    notify.success('Audit logs exported successfully');
  } catch (error) {
    console.error('Failed to export logs:', error);
    notify.error('Failed to export logs');
  }
};

// Detail dialog methods
const openDetailDialog = (logEntry: AuditLogEntry) => {
  selectedLogEntry.value = logEntry;
  showDetailDialog.value = true;
};

const navigateToLog = (logEntry: AuditLogEntry) => {
  selectedLogEntry.value = logEntry;
  // Dialog stays open, just updates content
};

const toggleAutoRefresh = (enabled: boolean) => {
  if (enabled) {
    autoRefreshInterval.value = setInterval(() => {
      // Load logs and metrics in parallel during auto-refresh
      Promise.all([loadAuditLogs(), loadAuditMetrics()]).catch((error) => {
        console.error('Error in auto-refresh:', error);
      });
    }, 30000);
  } else {
    if (autoRefreshInterval.value) {
      clearInterval(autoRefreshInterval.value);
      autoRefreshInterval.value = null;
    }
  }
};

// Toggle row expansion for inline details
const toggleRowExpand = (logId: string) => {
  expandedRows[logId] = !expandedRows[logId];
};

// Lifecycle
onMounted(() => {
  // Clean up error_reload parameter from URL if present
  // This prevents confusion when the error was from a previous page load
  const url = new URL(window.location.href);
  if (url.searchParams.has('error_reload')) {
    url.searchParams.delete('error_reload');
    window.history.replaceState({}, document.title, url.toString());
  }

  // Initialize previous values after component mounts
  // This prevents showing change notifications on initial load
  previousValues.value = {
    selectedTimePreset: selectedTimePreset.value,
    selectedActionTypes: [...selectedActionTypes.value],
    selectedResourceTypes: [...selectedResourceTypes.value],
    searchTerm: searchTerm.value,
  };

  // Load logs and metrics in parallel
  Promise.all([loadAuditLogs(), loadAuditMetrics()]).catch((error) => {
    console.error('Error in onMounted:', error);
  });

  // Check and show disabled popup AFTER fetching preference
  // This ensures the preference is loaded before popup decision
  fetchAuditTrailPreference()
    .then(() => {
      checkAndShowDisabledPopup();
    })
    .catch((error) => {
      console.error('Error fetching audit trail preference:', error);
    });
});

onBeforeUnmount(() => {
  if (autoRefreshInterval.value) {
    clearInterval(autoRefreshInterval.value);
  }
});
</script>

